package generated;

import com.openjiuwen.core.foundation.tool.Tool;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Read-only adapter over the pinned account balance transport.
 * Reports only fields returned by the transport; never invents balance data.
 */
public final class AccountBalanceTool extends Tool {
  private final Tool transport;

  public AccountBalanceTool(Tool transport) {
    super(transport.getCard());
    this.transport = transport;
  }

  @Override
  protected Object invokeInternal(Map<String, Object> inputs, Map<String, Object> kwargs)
      throws Exception {
    if (inputs == null || inputs.size() != 1) {
      throw new IllegalArgumentException("TOOL_INPUT_CONTRACT_INVALID");
    }
    Object accountIdValue = inputs.get("accountId");
    if (!(accountIdValue instanceof String)) {
      throw new IllegalArgumentException("TOOL_INPUT_CONTRACT_INVALID");
    }
    String accountId = (String) accountIdValue;
    if (accountId.trim().isEmpty()) {
      throw new IllegalArgumentException("TOOL_INPUT_CONTRACT_INVALID");
    }

    // Only the validated accountId crosses the boundary; trusted kwargs pass through unchanged.
    Object response = transport.invoke(Map.of("accountId", accountId), kwargs);

    if (!(response instanceof Map)) {
      throw new IllegalStateException("TOOL_RESPONSE_CONTRACT_INVALID");
    }
    Map<?, ?> raw = (Map<?, ?>) response;
    Object responseAccountId = raw.get("accountId");
    Object currency = raw.get("currency");
    Object availableBalanceFen = raw.get("availableBalanceFen");
    Object asOf = raw.get("asOf");

    if (!(responseAccountId instanceof String)
        || !(currency instanceof String)
        || !(availableBalanceFen instanceof Integer || availableBalanceFen instanceof Long)
        || !(asOf instanceof String)) {
      throw new IllegalStateException("TOOL_RESPONSE_CONTRACT_INVALID");
    }

    Map<String, Object> result = new LinkedHashMap<>();
    result.put("accountId", responseAccountId);
    result.put("currency", currency);
    result.put("availableBalanceFen", availableBalanceFen);
    result.put("asOf", asOf);
    return result;
  }
}
